import React from "react";
import Slider from "react-slick";
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

const EventsSlider = () => {
  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 1,
    slidesToScroll: 1,
    arrows: true,
  };

  return (
    <div
      style={{
        position: "relative",
        width: "100%",
        maxWidth: "1024px",
        height: "394.42px",
        margin: "0 auto",
        background: "#293349",
        border: "15px solid #00C26D",
        display: "flex",
        flexDirection: "column",
        padding: "0",
        gap: "4px",
      }}
    >
      <Slider {...settings}>
        {[1, 2, 3].map((num) => (
          <div
            key={num}
            style={{
              height: "373px",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              color: "#fff",
              fontSize: "24px",
              fontWeight: "bold",
              background: "#293349",
            }}
          >
            Slide {num}
          </div>
        ))}
      </Slider>

      {/* Kesik Çizgiler ve Dots */}
      <div
        style={{
          position: "absolute",
          top: "10px",
          left: "10px",
          display: "flex",
          flexDirection: "column",
          gap: "10px",
        }}
      >
        <div
          style={{
            width: "30.16px",
            height: "11.11px",
            background: "#293349",
          }}
        ></div>
        <div
          style={{
            width: "30.16px",
            height: "11.11px",
            background: "#293349",
          }}
        ></div>
      </div>
      <div
        style={{
          position: "absolute",
          top: "10px",
          right: "10px",
          display: "flex",
          flexDirection: "row",
          gap: "10px",
        }}
      >
        <div
          style={{
            width: "142.57px",
            height: "17.42px",
            background: "#293349",
          }}
        ></div>
      </div>
    </div>
  );
};

export default EventsSlider;
